query getAlertOnChangeTimeSeries(
  $monitorUuid: String!
  $contextHash: String!
  $alertContext: String
  $timeFrame: IssueTimeFrameForWidget!
  $monitorType: String
) {
  timeSeriesData(
    monitorUuid: $monitorUuid
    context: $alertContext
    timeFrame: $timeFrame
    monitorType: $monitorType
  ) {
    metric {
      dataPoints {
        time
        value
      }
    }
    baseline {
      dataPoints {
        time
        value
      }
    }
    threshold {
      dataPoints {
        time
        value
      }
    }
  }
  timeSeriesIssuePeriods(
    monitorUuid: $monitorUuid
    contextHash: $contextHash
    timeFrame: $timeFrame
  ) {
    periods {
      fromDate
      toDate
    }
    count
  }
}
